/**
 * TTOken Code Android device panel: the devices adb on this computer lists, the selected device's screen, which a
 * click taps and a drag swipes, navigation keys, typed text, a mirror window, and a note that hands the device to the
 * agent.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/client/DevicePanel.tsx; edit it there.
 */

import { useEffect, useRef, useState, type FormEvent, type PointerEvent, type ReactElement } from 'react'
import clsx from 'clsx'
import type { IconProps } from '@deepseek-ai/dsh-client-ui-primitives'
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { RemoteResult } from '@deepseek-ai/dsh-typert-protocol'
import { assertNever } from '@deepseek-ai/dsh-util-values'
import type { AndroidDevice, AndroidDeviceList, AndroidEmulatorList, DeviceInput, DeviceKey, DeviceScreen } from '../types.ts'
import type { NS } from './locales.ts'
import css from './DevicePanel.module.css'

/** Milliseconds between the end of one screenshot and the start of the next while the panel shows a device. */
const SCREEN_INTERVAL_MS = 1_000
/** Milliseconds after an input before the screen is read again, so the device has drawn the result. */
const AFTER_INPUT_MS = 350
/** Pointer travel in CSS pixels under which a press is a tap rather than a swipe. */
const TAP_SLOP = 8
/** Shortest and longest swipe the panel sends, in milliseconds. */
const SWIPE_MS = { min: 120, max: 2_000 } as const
/** Milliseconds after an emulator starts at which the panel looks for devices again, while it boots. */
const BOOT_CHECKS_MS = [12_000, 30_000, 60_000] as const

type Translate = PropsLocale<typeof NS>['t']

/** Business face injected by the panel's registration. */
export interface DevicePanelInjected {
  /**
   * List the devices adb on the Host sees.
   * @param signal - cancellation of the read.
   * @returns the devices, or why adb is missing.
   */
  listDevices: (signal: AbortSignal) => Promise<RemoteResult<AndroidDeviceList>>
  /**
   * Take a screenshot of a device.
   * @param serial - adb serial.
   * @param signal - cancellation of the read.
   * @returns the PNG image and its size.
   */
  readScreen: (serial: string, signal: AbortSignal) => Promise<RemoteResult<DeviceScreen>>
  /**
   * Send one input to a device.
   * @param serial - adb serial.
   * @param input - tap, swipe, text, or key.
   * @returns completion, or why the device did not take it.
   */
  send: (serial: string, input: DeviceInput) => Promise<RemoteResult<void>>
  /**
   * List the Android Virtual Devices the emulator can start.
   * @param signal - cancellation of the read.
   * @returns the AVD names, or why the emulator is missing.
   */
  listEmulators: (signal: AbortSignal) => Promise<RemoteResult<AndroidEmulatorList>>
  /**
   * Start an Android Virtual Device in its own window.
   * @param name - AVD name.
   * @returns completion, or why the emulator did not start.
   */
  startEmulator: (name: string) => Promise<RemoteResult<void>>
  /**
   * Open a mirror window of a device on the Host's desktop.
   * @param serial - adb serial.
   * @returns completion, or why the window did not open.
   */
  openMirror: (serial: string) => Promise<RemoteResult<void>>
  /**
   * Append a note to the Session's message draft and focus the composer.
   * @param note - text to append.
   * @returns whether the Session had a composer to take it.
   */
  addToDraft: (note: string) => boolean
  /** Open the Android platform-tools download page. */
  openPlatformTools: () => void
}

/** Full props of the panel body. */
export type DevicePanelProps = PropsRuntime<'sidebar.right.pane.tab'> & DevicePanelInjected & PropsLocale<typeof NS>

/** The device list as the panel last read it. */
type DeviceState =
  | { readonly kind: 'loading' }
  | { readonly kind: 'ready'; readonly devices: readonly AndroidDevice[] }
  | { readonly kind: 'missing'; readonly message: string }
  | { readonly kind: 'failed'; readonly message: string }

/** Where a press on the screen started. */
interface Press {
  readonly x: number
  readonly y: number
  readonly at: number
}

/**
 * The device panel body.
 * @param props - tab props with the panel's injected face.
 * @returns the panel.
 */
export function DevicePanel(props: DevicePanelProps): ReactElement {
  const { t, listDevices, listEmulators, readScreen, send, openMirror, startEmulator, addToDraft, openPlatformTools } = props
  const [state, setState] = useState<DeviceState>({ kind: 'loading' })
  const [selected, setSelected] = useState<string | null>(null)
  const [pickerOpen, setPickerOpen] = useState(false)
  const [screen, setScreen] = useState<DeviceScreen | null>(null)
  const [screenError, setScreenError] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)
  const [text, setText] = useState('')
  const [reload, setReload] = useState(0)
  const [frame, setFrame] = useState(0)
  const [avds, setAvds] = useState<readonly string[]>([])
  const press = useRef<Press | null>(null)
  const bootChecks = useRef<number[]>([])

  useEffect(() => {
    const controller = new AbortController()
    setState({ kind: 'loading' })
    void listDevices(controller.signal).then((result) => {
      if (controller.signal.aborted) return
      if (!result.ok) {
        setState({ kind: 'failed', message: result.error.message })
        return
      }
      const list = result.value
      if (list.adb === 'missing') {
        setState({ kind: 'missing', message: list.message })
        return
      }
      setState({ kind: 'ready', devices: list.devices })
      setSelected(current => list.devices.some(device => device.serial === current)
        ? current : list.devices.find(device => device.state === 'device')?.serial ?? list.devices[0]?.serial ?? null)
    }, (error: unknown) => {
      if (!controller.signal.aborted) setState({ kind: 'failed', message: messageOf(error) })
    })
    void listEmulators(controller.signal).then((result) => {
      if (!controller.signal.aborted) setAvds(result.ok && result.value.emulator === 'ready' ? result.value.names : [])
    }, () => { if (!controller.signal.aborted) setAvds([]) })
    return () => { controller.abort() }
  }, [listDevices, listEmulators, reload])

  useEffect(() => () => { for (const timer of bootChecks.current) window.clearTimeout(timer) }, [])

  const devices = state.kind === 'ready' ? state.devices : []
  const device = devices.find(candidate => candidate.serial === selected) ?? null
  const usable = device !== null && device.state === 'device'
  const serial = usable ? device.serial : null

  useEffect(() => {
    setScreen(null)
    setScreenError(null)
  }, [serial])

  // Reads the screen now and then once a second; an input bumps `frame` to read it again soon after.
  useEffect(() => {
    if (serial === null) return undefined
    const controller = new AbortController()
    let timer: number | undefined
    const next = (): void => {
      timer = window.setTimeout(read, SCREEN_INTERVAL_MS)
    }
    const read = (): void => {
      if (document.hidden) {
        next()
        return
      }
      void readScreen(serial, controller.signal).then((result) => {
        if (controller.signal.aborted) return
        if (result.ok) {
          setScreen(result.value)
          setScreenError(null)
        } else {
          setScreenError(result.error.message)
        }
        next()
      }, (error: unknown) => {
        if (controller.signal.aborted) return
        setScreenError(messageOf(error))
        next()
      })
    }
    read()
    return () => {
      controller.abort()
      window.clearTimeout(timer)
    }
  }, [readScreen, serial, frame])

  const sendInput = (input: DeviceInput): void => {
    if (serial === null) return
    void send(serial, input).then((result) => {
      if (!result.ok) {
        setNotice(t('input.failed', { message: result.error.message }))
        return
      }
      setNotice(null)
      window.setTimeout(() => { setFrame(value => value + 1) }, AFTER_INPUT_MS)
    }, (error: unknown) => { setNotice(t('input.failed', { message: messageOf(error) })) })
  }

  const pointToDevice = (event: PointerEvent<HTMLImageElement>): { x: number; y: number } | null => {
    if (screen === null) return null
    const box = event.currentTarget.getBoundingClientRect()
    if (box.width === 0 || box.height === 0) return null
    const x = Math.round((event.clientX - box.left) / box.width * screen.width)
    const y = Math.round((event.clientY - box.top) / box.height * screen.height)
    return { x: clamp(x, 0, screen.width - 1), y: clamp(y, 0, screen.height - 1) }
  }

  const onPointerDown = (event: PointerEvent<HTMLImageElement>): void => {
    if (event.button !== 0) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    press.current = { x: event.clientX, y: event.clientY, at: Date.now() }
  }

  const onPointerUp = (event: PointerEvent<HTMLImageElement>): void => {
    const start = press.current
    press.current = null
    if (start === null) return
    const end = pointToDevice(event)
    if (end === null) return
    if (Math.hypot(event.clientX - start.x, event.clientY - start.y) < TAP_SLOP) {
      sendInput({ kind: 'tap', ...end })
      return
    }
    const box = event.currentTarget.getBoundingClientRect()
    if (screen === null || box.width === 0 || box.height === 0) return
    const from = {
      x: clamp(Math.round((start.x - box.left) / box.width * screen.width), 0, screen.width - 1),
      y: clamp(Math.round((start.y - box.top) / box.height * screen.height), 0, screen.height - 1),
    }
    const durationMs = clamp(Date.now() - start.at, SWIPE_MS.min, SWIPE_MS.max)
    sendInput({ kind: 'swipe', fromX: from.x, fromY: from.y, toX: end.x, toY: end.y, durationMs })
  }

  const submitText = (event: FormEvent<HTMLFormElement>): void => {
    event.preventDefault()
    if (text === '') return
    sendInput({ kind: 'text', text })
    setText('')
  }

  const mirror = (): void => {
    if (serial === null) return
    void openMirror(serial).then((result) => {
      setNotice(result.ok ? null : t('mirror.failed', { message: result.error.message }))
    }, (error: unknown) => { setNotice(t('mirror.failed', { message: messageOf(error) })) })
  }

  const startAvd = (name: string): void => {
    setPickerOpen(false)
    void startEmulator(name).then((result) => {
      if (!result.ok) {
        setNotice(t('emulator.failed', { message: result.error.message }))
        return
      }
      setNotice(t('emulator.starting', { name: avdLabelOf(name) }))
      bootChecks.current = BOOT_CHECKS_MS.map(delay => window.setTimeout(() => { setReload(value => value + 1) }, delay))
    }, (error: unknown) => { setNotice(t('emulator.failed', { message: messageOf(error) })) })
  }

  const handToAgent = (): void => {
    if (device === null) return
    const name = nameOf(device, t)
    const added = addToDraft(t('agent.prompt', { name, serial: device.serial }))
    setNotice(added ? t('agent.added') : t('agent.noComposer'))
  }

  return (
    <div className={css.root}>
      <div className={css.head}>
        <div className={css.pickerWrap}>
          <button
            type="button"
            className={css.picker}
            aria-haspopup="menu"
            aria-expanded={pickerOpen}
            disabled={devices.length === 0 && avds.length === 0}
            onClick={() => { setPickerOpen(open => !open) }}
          >
            <PhoneGlyph />
            <span className={css.pickerText}>
              <span className={css.pickerName}>{device === null ? t('picker.none') : nameOf(device, t)}</span>
              {device !== null && (
                <span className={css.pickerNote}>
                  <span aria-hidden="true" className={clsx(css.dot, usable ? css.dotReady : css.dotWaiting)} />
                  {noteOf(device, t)}
                </span>
              )}
            </span>
            <ChevronGlyph />
          </button>
          {pickerOpen && (devices.length > 0 || avds.length > 0) && (
            <div role="menu" aria-label={t('picker.label')} className={css.menu}>
              {devices.length > 0 && <p className={css.menuHeading}>{t('picker.heading')}</p>}
              {devices.map(candidate => (
                <button
                  key={candidate.serial}
                  type="button"
                  role="menuitemradio"
                  aria-checked={candidate.serial === selected}
                  className={css.menuItem}
                  onClick={() => {
                    setSelected(candidate.serial)
                    setPickerOpen(false)
                  }}
                >
                  <span className={css.menuName}>{nameOf(candidate, t)}</span>
                  <span className={css.menuNote}>{noteOf(candidate, t)}</span>
                </button>
              ))}
              {avds.length > 0 && <p className={css.menuHeading}>{t('emulator.heading')}</p>}
              {avds.map(name => (
                <button key={name} type="button" role="menuitem" className={css.menuItem} onClick={() => { startAvd(name) }}>
                  <span className={css.menuName}>{t('emulator.start', { name: avdLabelOf(name) })}</span>
                </button>
              ))}
            </div>
          )}
        </div>
        <button
          type="button"
          className={css.iconButton}
          aria-label={t('refresh')}
          title={t('refresh')}
          onClick={() => {
            setPickerOpen(false)
            setReload(value => value + 1)
          }}
        >
          <RefreshGlyph />
        </button>
      </div>

      <div className={css.body}>
        <DeviceBody
          state={state}
          avds={avds}
          startAvd={startAvd}
          device={device}
          screen={screen}
          screenError={screenError}
          t={t}
          openPlatformTools={openPlatformTools}
          onPointerDown={onPointerDown}
          onPointerUp={onPointerUp}
        />
      </div>

      {usable && (
        <div className={css.controls}>
          <div role="toolbar" aria-label={t('controls.label')} className={css.toolbar}>
            {(['back', 'home', 'recents'] as const).map(key => (
              <button
                key={key}
                type="button"
                className={css.tool}
                aria-label={t(`key.${key}`)}
                title={t(`key.${key}`)}
                onClick={() => { sendInput({ kind: 'key', key }) }}
              >
                <KeyGlyph name={key} />
              </button>
            ))}
            <button type="button" className={css.tool} aria-label={t('mirror')} title={t('mirror')} onClick={mirror}>
              <MirrorGlyph />
            </button>
          </div>
          <form className={css.typeRow} onSubmit={submitText}>
            <input
              className={css.typeInput}
              value={text}
              placeholder={t('type.placeholder')}
              aria-label={t('type.label')}
              onChange={(event) => { setText(event.target.value) }}
            />
            <button type="submit" className={css.secondary} disabled={text === ''}>{t('type.send')}</button>
          </form>
          <button type="button" className={css.primary} onClick={handToAgent}>{t('agent.button')}</button>
          <p className={css.note}>{t('agent.note')}</p>
        </div>
      )}

      {notice !== null && <p role="status" className={css.notice}>{notice}</p>}
      <p className={css.footer}>
        <LinkGlyph />
        {t('footer')}
      </p>
    </div>
  )
}

/** Props of the panel's middle: the screen, or why there is none. */
interface DeviceBodyProps {
  readonly state: DeviceState
  readonly avds: readonly string[]
  readonly startAvd: (name: string) => void
  readonly device: AndroidDevice | null
  readonly screen: DeviceScreen | null
  readonly screenError: string | null
  readonly t: Translate
  readonly openPlatformTools: () => void
  readonly onPointerDown: (event: PointerEvent<HTMLImageElement>) => void
  readonly onPointerUp: (event: PointerEvent<HTMLImageElement>) => void
}

/** The selected device's screen, or the state that keeps it from showing. */
function DeviceBody(props: DeviceBodyProps): ReactElement {
  const { state, avds, startAvd, device, screen, screenError, t, openPlatformTools, onPointerDown, onPointerUp } = props
  switch (state.kind) {
    case 'loading':
      return <p className={css.state}>{t('loading')}</p>
    case 'missing':
      return (
        <div className={css.state}>
          <p className={css.stateTitle}>{t('adbMissing.title')}</p>
          <p>{t('adbMissing.note')}</p>
          <button type="button" className={css.secondary} onClick={openPlatformTools}>{t('adbMissing.link')}</button>
        </div>
      )
    case 'failed':
      return (
        <div className={css.state}>
          <p className={css.stateTitle}>{t('failed')}</p>
          <p className={css.detail}>{state.message}</p>
        </div>
      )
    case 'ready':
      break
    default:
      return assertNever(state)
  }
  if (device === null) {
    return (
      <div className={css.state}>
        <p className={css.stateTitle}>{t('none.title')}</p>
        <p>{t('none.note')}</p>
        {avds.map(name => (
          <button key={name} type="button" className={css.secondary} onClick={() => { startAvd(name) }}>
            {t('emulator.start', { name: avdLabelOf(name) })}
          </button>
        ))}
      </div>
    )
  }
  if (device.state !== 'device') {
    return <p className={css.state}>{device.state === 'unauthorized' ? t('unauthorized') : t('offline')}</p>
  }
  if (screen === null) {
    return <p className={css.state}>{screenError === null ? t('screen.loading') : t('screen.failed', { message: screenError })}</p>
  }
  return (
    <div className={css.screenWrap}>
      <img
        className={css.screen}
        src={`data:image/png;base64,${screen.png}`}
        width={screen.width}
        height={screen.height}
        alt={t('screen.label', { name: nameOf(device, t) })}
        draggable={false}
        onPointerDown={onPointerDown}
        onPointerUp={onPointerUp}
      />
      {screenError !== null && <p className={css.screenError}>{t('screen.failed', { message: screenError })}</p>}
    </div>
  )
}

/**
 * The title chip of the device tab.
 * @param props - tab title props.
 * @returns the title.
 */
export function DeviceTitle({ t }: PropsRuntime<'sidebar.right.pane.tab.title'> & PropsLocale<typeof NS>): ReactElement {
  return <><PhoneGlyph />{t('title')}</>
}

/** A device's model, or a generic name when adb reports none. */
function nameOf(device: AndroidDevice, t: Translate): string {
  return device.model ?? t('unnamed')
}

/** An AVD name as people read it: `Pixel_9_API_35` reads as `Pixel 9 API 35`. */
function avdLabelOf(name: string): string {
  return name.replaceAll('_', ' ')
}

/** How a device is connected and whether it is ready. */
function noteOf(device: AndroidDevice, t: Translate): string {
  const status = device.state === 'device' ? t('state.ready') : device.state === 'unauthorized' ? t('state.unauthorized') : t('state.other')
  return t('device.note', { transport: t(`transport.${device.transport}`), status })
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/**
 * Guide artwork of the device tab: a phone.
 * @param props - size and class.
 * @returns the glyph.
 */
export function DeviceArtwork({ size = 36, className }: IconProps): ReactElement {
  return (
    <svg width={size} height={size} className={className} viewBox="0 0 36 36" fill="none" aria-hidden="true">
      <rect x="11" y="5" width="14" height="26" rx="3.5" stroke="#3DDC84" strokeWidth="3" />
      <path d="M16 26.5h4" stroke="#3DDC84" strokeWidth="3" strokeLinecap="round" />
    </svg>
  )
}

function PhoneGlyph(): ReactElement {
  return (
    <svg className={css.glyph} width="16" height="16" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="6" y="2.5" width="8" height="15" rx="2" />
      <path d="M9 14.5h2" />
    </svg>
  )
}

function ChevronGlyph(): ReactElement {
  return (
    <svg className={css.glyph} width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M6 8l4 4 4-4" />
    </svg>
  )
}

function RefreshGlyph(): ReactElement {
  return (
    <svg width="16" height="16" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M15.5 9.5A5.5 5.5 0 1 1 13.9 5.6M15.5 3.5v3.5H12" />
    </svg>
  )
}

function KeyGlyph({ name }: { readonly name: Extract<DeviceKey, 'back' | 'home' | 'recents'> }): ReactElement {
  switch (name) {
    case 'back':
      return (
        <svg width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M14 5v10L6 10z" />
        </svg>
      )
    case 'home':
      return (
        <svg width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true">
          <circle cx="10" cy="10" r="5" />
        </svg>
      )
    case 'recents':
      return (
        <svg width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" aria-hidden="true">
          <rect x="5" y="5" width="10" height="10" rx="1.5" />
        </svg>
      )
    default:
      return assertNever(name)
  }
}

function MirrorGlyph(): ReactElement {
  return (
    <svg width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="2.5" y="4" width="15" height="10" rx="1.5" />
      <path d="M7 17h6M10 14v3" />
    </svg>
  )
}

function LinkGlyph(): ReactElement {
  return (
    <svg className={css.glyph} width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" aria-hidden="true">
      <path d="M8.5 11.5l3-3M7 9.5L5.5 11a2.5 2.5 0 0 0 3.5 3.5l1.5-1.5M13 10.5l1.5-1.5a2.5 2.5 0 0 0-3.5-3.5L9.5 7" />
    </svg>
  )
}
